"use client";
import { useState, useEffect, useRef } from "react";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import SettingsModal from "./SettingsModal";
import SearchView from "./SearchView";
import { extractSubCategories, extractVodSubCategories } from "@/lib/subcategories";

export default function Navbar({
    activeFilter,
    onFilterChange,
    activeSubFilter = "all",
    onSubFilterChange,
    onSelectCategoryAndSub,
    dynamicSubCategories,
    onSearch,
    isSearchOpen: propIsSearchOpen,
    setIsSearchOpen: propSetIsSearchOpen,
    searchVal: propSearchVal,
    setSearchVal: propSetSearchVal,
    isClosingSearch: propIsClosingSearch,
    onCloseSearch: propOnCloseSearch
}) {
    const pathname = usePathname();
    const router = useRouter();
    const [localIsSearchOpen, setLocalIsSearchOpen] = useState(false);
    const [localSearchVal, setLocalSearchVal] = useState("");

    const isSearchOpen = propIsSearchOpen !== undefined ? propIsSearchOpen : localIsSearchOpen;
    const setIsSearchOpen = propSetIsSearchOpen || setLocalIsSearchOpen;
    const searchVal = propSearchVal !== undefined ? propSearchVal : localSearchVal;
    const setSearchVal = propSetSearchVal || setLocalSearchVal;

    const [isSettingsOpen, setIsSettingsOpen] = useState(false);
    const [isNavHidden, setIsNavHidden] = useState(false);
    const [isScrolled, setIsScrolled] = useState(false);
    const [mounted, setMounted] = useState(false);
    const [openDropdownNav, setOpenDropdownNav] = useState(null);
    const [cachedSubCategories, setCachedSubCategories] = useState({
        sport: [],
        intrattenimento: [],
        eventi: [],
        vod: []
    });
    const [localIsClosingSearch, setLocalIsClosingSearch] = useState(false);
    const isClosingSearch = propIsClosingSearch !== undefined ? propIsClosingSearch : localIsClosingSearch;
    const hoverTimeoutRef = useRef(null);
    const searchWrapperRef = useRef(null);
    const searchInputRef = useRef(null);

    // Carica e aggiorna le sottocategorie disponibili in background
    useEffect(() => {
        function refreshSubCategories() {
            try {
                let sections = [];
                const storedSec = localStorage.getItem("nmdz_cached_sections");
                if (storedSec) sections = JSON.parse(storedSec);

                let vodSec = [];
                const storedVod = localStorage.getItem("nmdz_cached_vod");
                if (storedVod) vodSec = JSON.parse(storedVod);

                setCachedSubCategories({
                    sport: extractSubCategories(sections, "sport"),
                    intrattenimento: extractSubCategories(sections, "intrattenimento"),
                    eventi: extractSubCategories(sections, "eventi"),
                    vod: extractVodSubCategories(vodSec)
                });
            } catch (e) {}
        }

        refreshSubCategories();
        window.addEventListener("nmdz:sections_updated", refreshSubCategories);
        window.addEventListener("nmdz:vod_updated", refreshSubCategories);
        return () => {
            window.removeEventListener("nmdz:sections_updated", refreshSubCategories);
            window.removeEventListener("nmdz:vod_updated", refreshSubCategories);
        };
    }, []);

    // Chiusura al click all'esterno del menu
    useEffect(() => {
        function handleClickOutside(e) {
            if (!e.target.closest(".dock-nav-item-wrapper")) {
                setOpenDropdownNav(null);
            }
        }
        document.addEventListener("click", handleClickOutside);
        return () => document.removeEventListener("click", handleClickOutside);
    }, []);

    const effectiveSubCategories = dynamicSubCategories || cachedSubCategories;

    // DROPDOWN HOVER: Si attiva ESCLUSIVAMENTE al passaggio del mouse sopra la freccia o il dropdown stesso
    const handleArrowMouseEnter = (tabId) => {
        if (hoverTimeoutRef.current) clearTimeout(hoverTimeoutRef.current);
        setOpenDropdownNav(tabId);
    };

    const handleArrowMouseLeave = () => {
        if (hoverTimeoutRef.current) clearTimeout(hoverTimeoutRef.current);
        hoverTimeoutRef.current = setTimeout(() => {
            setOpenDropdownNav(null);
        }, 200);
    };

    const handleDropdownMouseEnter = () => {
        if (hoverTimeoutRef.current) clearTimeout(hoverTimeoutRef.current);
    };

    const handleDropdownMouseLeave = () => {
        if (hoverTimeoutRef.current) clearTimeout(hoverTimeoutRef.current);
        hoverTimeoutRef.current = setTimeout(() => {
            setOpenDropdownNav(null);
        }, 200);
    };

    const handleToggleArrow = (e, tab) => {
        e.preventDefault();
        e.stopPropagation();
        setOpenDropdownNav(prev => (prev === tab ? null : tab));
    };

    const handleSubCategoryClick = (macroTab, subId) => {
        setOpenDropdownNav(null);
        if (onSelectCategoryAndSub) {
            onSelectCategoryAndSub(macroTab, subId);
        } else {
            const cleanMacro = (macroTab === "home" || macroTab === "all") ? "all" : macroTab;
            if (onFilterChange) {
                onFilterChange(cleanMacro);
                if (onSubFilterChange) onSubFilterChange(subId);
            } else {
                const target = cleanMacro === "all" ? "/home" : `/${cleanMacro}`;
                router.push(subId && subId !== "all" ? `${target}?sub=${encodeURIComponent(subId)}` : target);
            }
        }
    };

    useEffect(() => {
        setMounted(true);
    }, []);

    const isPlayerPage = pathname ? pathname.startsWith("/sky") : false;
    const lastScrollYRef = useRef(0);

    useEffect(() => {
        if (isPlayerPage) {
            setIsNavHidden(false);
            setIsScrolled(false);
            return;
        }

        let ticking = false;

        function getScrollY() {
            return window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || window.scrollY || 0;
        }

        function updateScroll() {
            if (isPlayerPage) {
                setIsNavHidden(false);
                setIsScrolled(false);
                ticking = false;
                return;
            }

            const currentScrollY = getScrollY();
            const lastScrollY = lastScrollYRef.current;
            const delta = currentScrollY - lastScrollY;

            setIsScrolled(currentScrollY > 15);

            if (currentScrollY <= 40) {
                setIsNavHidden(false);
            } else if (delta > 8 && currentScrollY > 70) {
                setIsNavHidden(true);
            } else if (delta < -8) {
                setIsNavHidden(false);
            }

            lastScrollYRef.current = currentScrollY <= 0 ? 0 : currentScrollY;
            ticking = false;
        }

        function onScroll() {
            if (!ticking) {
                window.requestAnimationFrame(updateScroll);
                ticking = true;
            }
        }

        window.addEventListener("scroll", onScroll, { passive: true });
        return () => {
            window.removeEventListener("scroll", onScroll);
        };
    }, [isPlayerPage, pathname]);

    useEffect(() => {
        setIsNavHidden(false);
        setIsSearchOpen(false);
        const cur = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || window.scrollY || 0;
        lastScrollYRef.current = cur;
        setIsScrolled(cur > 15);
    }, [pathname, activeFilter, isPlayerPage]);

    const handleNavClick = (filter) => {
        const cleanFilter = (filter === "home" || filter === "all") ? "all" : filter;
        let targetPath = "/home";
        if (cleanFilter === "sport") targetPath = "/sport";
        else if (cleanFilter === "intrattenimento") targetPath = "/intrattenimento";
        else if (cleanFilter === "eventi") targetPath = "/eventi";
        else if (cleanFilter === "vod") targetPath = "/vod";

        try {
            window.scrollTo({ top: 0, behavior: "instant" });
        } catch(e) {
            window.scrollTo(0, 0);
        }
        setIsNavHidden(false);
        setIsScrolled(false);
        lastScrollYRef.current = 0;

        if (onFilterChange) {
            onFilterChange(cleanFilter);
        } else {
            router.push(targetPath);
        }
    };

    useEffect(() => {
        if (!isSearchOpen) return;

        function handleKeyDown(e) {
            if (e.key === "Escape") {
                handleCloseSearch();
            }
        }

        window.addEventListener("keydown", handleKeyDown);
        return () => {
            window.removeEventListener("keydown", handleKeyDown);
        };
    }, [isSearchOpen]);

    const isStandaloneSearch = onSearch === undefined;

    useEffect(() => {
        if (isStandaloneSearch && isSearchOpen) {
            const originalHtmlOverflow = document.documentElement.style.overflow;
            const originalBodyOverflow = document.body.style.overflow;
            document.documentElement.style.overflow = "hidden";
            document.body.style.overflow = "hidden";
            return () => {
                document.documentElement.style.overflow = originalHtmlOverflow;
                document.body.style.overflow = originalBodyOverflow;
            };
        }
    }, [isStandaloneSearch, isSearchOpen]);

    const handleSearchChange = (val) => {
        setSearchVal(val);
        if (onSearch) onSearch(val);
    };

    const handleOpenSearch = () => {
        setIsSearchOpen(true);
        setTimeout(() => {
            if (searchInputRef.current) searchInputRef.current.focus();
        }, 60);
    };

    const handleCloseSearch = () => {
        if (isClosingSearch) return;
        if (propOnCloseSearch) {
            propOnCloseSearch();
        } else {
            setLocalIsClosingSearch(true);
            setTimeout(() => {
                setIsSearchOpen(false);
                setLocalIsClosingSearch(false);
                setSearchVal("");
                if (onSearch) onSearch("");
            }, 180);
        }
    };

    const isHidden = isNavHidden && !isSearchOpen;

    return (
        <>
            <div className={`home-header-wrapper ${mounted ? "is-mounted" : "is-mounting"} ${isHidden ? "nav-hidden" : ""} ${isSearchOpen ? "search-mode-active" : ""} ${isScrolled ? "header-scrolled" : "header-top"}`} id="home-header-wrapper">
                {isSearchOpen ? (
                    <div className={`home-search-fullbar-container ${isClosingSearch ? "is-closing" : ""}`} ref={searchWrapperRef}>
                        <div className="home-search-fullbar">
                            <i className="fas fa-magnifying-glass search-fullbar-icon"></i>
                            <input
                                ref={searchInputRef}
                                type="text"
                                className="search-fullbar-input"
                                placeholder="Cerca film, serie TV, eventi sportivi, canali..."
                                value={searchVal}
                                onChange={(e) => handleSearchChange(e.target.value)}
                                onKeyDown={(e) => {
                                    if (e.key === "Enter") {
                                        if (onSearch) {
                                            onSearch(searchVal);
                                        } else if (searchVal.trim()) {
                                            router.push(`/home?search=${encodeURIComponent(searchVal.trim())}`);
                                        }
                                    }
                                }}
                                autoFocus
                            />
                            <button
                                type="button"
                                className="search-fullbar-cancel-btn"
                                onClick={handleCloseSearch}
                                aria-label="Annulla ricerca"
                                title="Annulla ricerca (Esc)"
                            >
                                Annulla
                            </button>
                        </div>
                    </div>
                ) : (
                    <div className="home-header-dock-container fade-enter">
                        <header className="home-header-dock" role="banner">
                            {/* BRAND LOGO + CATEGORIE AFFIANCATE IN ALTO A SINISTRA */}
                            <div className="dock-group dock-group-left">
                                <Link
                                    href="/home"
                                    className="dock-brand-link"
                                    title="NMDZ - Home"
                                    aria-label="NMDZ Home"
                                    onClick={(e) => {
                                        e.preventDefault();
                                        handleCloseSearch();
                                        handleNavClick("all");
                                    }}
                                >
                                    <svg className="dock-brand-logo-svg" viewBox="0 0 512 512" fill="currentColor" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
                                        <polygon points="3.67,166.42 67.08,220.26 67.08,459.18 3.67,511.97" />
                                        <polygon points="12.2,5.03 221.73,182.93 221.73,456.97 240.23,439.46 240.23,5.03 289.49,5.03 289.49,392.83 240.23,439.46 221.73,456.97 289.49,511.97 289.49,439.46 508.33,270.03 314.16,157.02 314.16,236.42 431.11,304.38 314.16,394.94 314.16,346.06 228.61,427.11 67.08,290.01 67.08,51.81" />
                                    </svg>
                                    <span className="dock-brand-text">NMDZ</span>
                                </Link>

                                <nav className="dock-group-center" aria-label="Navigazione principale">
                                    {[
                                        { id: "all", path: "/home", label: "HOME", hasSub: false },
                                        { id: "sport", path: "/sport", label: "SPORT", hasSub: true },
                                        { id: "intrattenimento", path: "/intrattenimento", label: "INTRATTENIMENTO", hasSub: true },
                                        { id: "eventi", path: "/eventi", label: "EVENTI", hasSub: true },
                                        { id: "vod", path: "/vod", label: "VOD", hasSub: true }
                                    ].map((item) => {
                                        const isActive = activeFilter === item.id;
                                        const subItems = (item.hasSub && effectiveSubCategories[item.id]) ? effectiveSubCategories[item.id] : [];
                                        const isDropdownOpen = openDropdownNav === item.id;

                                        return (
                                            <div
                                                key={item.id}
                                                className={`dock-nav-item-wrapper ${isDropdownOpen ? "dropdown-active" : ""}`}
                                            >
                                                <Link
                                                    href={item.path}
                                                    className={`dock-nav-link ${isActive ? "active" : ""}`}
                                                    onClick={() => {
                                                        setOpenDropdownNav(null);
                                                        handleNavClick(item.id);
                                                        if (onSubFilterChange) onSubFilterChange("all");
                                                    }}
                                                >
                                                    <span className="dock-label">{item.label}</span>
                                                </Link>

                                                {item.hasSub && subItems.length > 0 && (
                                                    <button
                                                        type="button"
                                                        className={`dock-arrow-btn ${isDropdownOpen ? "is-open" : ""}`}
                                                        onMouseEnter={() => handleArrowMouseEnter(item.id)}
                                                        onMouseLeave={handleArrowMouseLeave}
                                                        onClick={(e) => handleToggleArrow(e, item.id)}
                                                        aria-label={`Sottocategorie ${item.label}`}
                                                        title={`Mostra sottocategorie ${item.label}`}
                                                    >
                                                        <span className="material-symbols-rounded dock-arrow-icon" aria-hidden="true">
                                                            keyboard_arrow_down
                                                        </span>
                                                    </button>
                                                )}

                                                {item.hasSub && subItems.length > 0 && (
                                                    <div
                                                        className={`dock-subnav-dropdown ${isDropdownOpen ? "is-open" : ""}`}
                                                        role="menu"
                                                        onMouseEnter={handleDropdownMouseEnter}
                                                        onMouseLeave={handleDropdownMouseLeave}
                                                    >
                                                        <div className="dock-dropdown-header">
                                                            <span>{item.label}</span>
                                                        </div>
                                                        <div className="dock-dropdown-list">
                                                            <button
                                                                type="button"
                                                                className={`dock-dropdown-item ${isActive && activeSubFilter === "all" ? "active" : ""}`}
                                                                onClick={() => handleSubCategoryClick(item.id, "all")}
                                                            >
                                                                <span className="dock-dropdown-dot"></span>
                                                                <span className="dock-dropdown-item-label">Tutti</span>
                                                            </button>
                                                            {subItems.map(sub => {
                                                                const isSubActive = isActive && activeSubFilter === sub.id;
                                                                return (
                                                                    <button
                                                                        key={sub.id}
                                                                        type="button"
                                                                        className={`dock-dropdown-item ${isSubActive ? "active" : ""}`}
                                                                        onClick={() => handleSubCategoryClick(item.id, sub.id)}
                                                                    >
                                                                        <span className="dock-dropdown-dot"></span>
                                                                        <span className="dock-dropdown-item-label">{sub.label}</span>
                                                                        {typeof sub.count === "number" && sub.count > 0 && (
                                                                            <span className="dock-dropdown-badge">{sub.count}</span>
                                                                        )}
                                                                    </button>
                                                                );
                                                            })}
                                                        </div>
                                                    </div>
                                                )}
                                            </div>
                                        );
                                    })}
                                </nav>
                            </div>

                            {/* AZIONI (CERCA, IMPOSTAZIONI) */}
                            <div className="dock-group dock-group-right">
                                <button
                                    type="button"
                                    className="dock-action-btn search-icon-btn"
                                    onClick={handleOpenSearch}
                                    aria-label="Cerca"
                                    title="Cerca canali, eventi, film..."
                                >
                                    <i className="fas fa-magnifying-glass"></i>
                                </button>

                                <button
                                    type="button"
                                    className="dock-action-btn settings-icon-btn"
                                    onClick={() => setIsSettingsOpen(true)}
                                    aria-label="Impostazioni"
                                    title="Impostazioni"
                                >
                                    <i className="fas fa-gear"></i>
                                </button>
                            </div>
                        </header>
                    </div>
                )}
            </div>
            
            {isStandaloneSearch && isSearchOpen && (
                <div 
                    className="global-search-modal-overlay" 
                    onClick={(e) => {
                        if (e.target.classList.contains("global-search-modal-overlay")) {
                            handleCloseSearch();
                        }
                    }}
                >
                    <SearchView
                        search={searchVal}
                        onSearchChange={handleSearchChange}
                        onClose={handleCloseSearch}
                        onSelectChannel={handleCloseSearch}
                    />
                </div>
            )}

            {isSettingsOpen && <SettingsModal onClose={() => setIsSettingsOpen(false)} />}
        </>
    );
}
